namespace CombatSolver;
internal sealed partial class CombatBeamSolver
{
    internal StateFingerprint TaskFiniteSourceKey(CombatPredictionSimulator simulator)
    {
        var combat=(SimulatedCombatState)simulator.State.CombatState;
        return BuildStateKey(combat.GetPlayerTurnNumber(_player),simulator.State.GetCreature(_player.Creature),
            simulator.State.GetPlayerCombatState(_player),combat,simulator,simulator.ShuffleEventCount,new HashSet<uint>());
    }
}

internal sealed partial class UnattendedTestRunner
{
    private async Task AssertFiniteSourcePipelineAsync(CombatState live, Player player)
    {
        SetStage("finite_source_pipeline");
        string[] sourceIds=["ASCENDERS_BANE","BACKSTAB","BLADE_OF_INK","BUBBLE_BUBBLE","DEFEND_SILENT","FAN_OF_KNIVES",
            "FLECHETTES","MASTER_PLANNER","NEUTRALIZE","NOXIOUS_FUMES","PRECISE_CUT","PREPARED","PROWESS","REFLEX",
            "ROLLING_BOULDER","STRIKE_SILENT","SURVIVOR","THE_HUNT","SHIV","FRANTIC_ESCAPE"];
        foreach(string id in sourceIds) await InjectCardAsync(live,player,new(){CardId=id,Pile="Exhaust"});
        foreach(string id in new[]{"NOXIOUS_FUMES","MASTER_PLANNER","BLADE_OF_INK"})
            await InjectCardAsync(live,player,new(){CardId=id,Pile="Hand",UpgradeLevels=1});
        SetEnergy(player,20);
        await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
        var root=CombatRootSnapshot.Capture(live);
        var policy=SolverController.CaptureSearchPolicy(SolverSettings.Capture(),live,false,null);
        var names=SolverDisplayNames.Capture(live);
        var solver=new CombatBeamSolver(root,names,BattleDamageTracker.Observe(live),policy,potionPolicyOverride:SolverPotionPolicy.Disabled);
        var parent=root.ForkSimulator();
        var lanes=Enumerable.Range(0,3).Select(_=>parent.Fork()).ToArray();
        var movable=parent.State.GetPlayerCombatState(player).ExhaustPile.Cards.Select(card=>card.Preview.GetType()).ToHashSet();
        static void Equal(string expected,string actual,string label)
        {if(expected!=actual)throw new InvalidOperationException(label+" differs\nEXPECTED\n"+expected+"\nACTUAL\n"+actual);}
        static string Hash(string value)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
        string State(CombatPredictionSimulator sim,CombatRootSnapshot captured)
            =>ContinuationStamp.CapturePredicted(player,sim,((SimulatedCombatState)sim.State.CombatState).GetPlayerTurnNumber(player),captured.Forecast,captured.StartTurnNumber).StateText;
        string Full(CombatPredictionSimulator sim,CombatRootSnapshot captured,CombatBeamSolver driver)
            =>State(sim,captured)+"\nKEY="+driver.TaskFiniteSourceKey(sim)+"\nHISTORY="+CardContinuationContractHistoryText(sim)
                +"\nFLAGS="+JsonSerializer.Serialize(new{sim.TerminalStamp,sim.IsInProgress,sim.IsAboutToLose});
        string Canonical(CombatPredictionSimulator sim,CombatRootSnapshot captured,CombatBeamSolver driver)
        {
            var clone=sim.Fork();var pile=clone.State.GetPlayerCombatState(player).ExhaustPile;
            var all=pile.Cards.ToArray();var free=all.Select((card,index)=>(card,index)).Where(pair=>movable.Contains(pair.card.Preview.GetType())
                    &&pair.card.Preview.Enchantment==null&&pair.card.Preview.Affliction==null)
                .OrderBy(pair=>pair.card.Preview.GetType().FullName,StringComparer.Ordinal).ThenBy(pair=>pair.index).Select(pair=>pair.card).ToArray();
            int next=0;for(int index=0;index<all.Length;index++)
                if(movable.Contains(all[index].Preview.GetType())&&all[index].Preview.Enchantment==null&&all[index].Preview.Affliction==null)all[index]=free[next++];
            pile.Clear();foreach(var card in all)pile.Add(card);
            return Full(clone,captured,driver);
        }
        for(int lane=1;lane<lanes.Length;lane++)
        {
            var pile=lanes[lane].State.GetPlayerCombatState(player).ExhaustPile;
            var all=lane==1?pile.Cards.OrderBy(card=>card.Preview.GetType().FullName,StringComparer.Ordinal).ToArray()
                :pile.Cards.OrderByDescending(card=>card.Preview.GetType().FullName,StringComparer.Ordinal).ToArray();
            pile.Clear();foreach(var card in all)pile.Add(card);
        }
        string parentBefore=Full(parent,root,solver);
        for(int lane=1;lane<lanes.Length;lane++)Equal(Canonical(lanes[0],root,solver),Canonical(lanes[lane],root,solver),"initial projected state");
        var steps=new List<object>();
        using var deadline=new CancellationTokenSource(TimeSpan.FromSeconds(55));
        void Shadow(CombatPredictionSimulator sim,Action<CombatPredictionSimulator> execute)
        {
            using IDisposable isolation=SimulationNotificationIsolation.Enter();
            var combat=(SimulatedCombatState)sim.State.CombatState;var deaths=new ForkableSet<uint>();
            using(combat.BeginCardExecutionScope(deaths))execute(sim);
            if(!CorePowerSupport.ApplyEnemyDeathPowers(sim,combat,combat.KnownEnemies,deaths)
                ||!CombatBeamSolver.SettleReplayActionBoundary(sim,combat)||sim.HasPendingChoice)
                throw new InvalidOperationException("Unexpected choice or incomplete action boundary.");
            sim.CheckWinCondition(combat.GetPlayerTurnNumber(player));
        }
        void CheckShadow(string label)
        {
            for(int lane=1;lane<lanes.Length;lane++)Equal(Canonical(lanes[0],root,solver),Canonical(lanes[lane],root,solver),label+" full projected state/history/RNG");
            Equal(parentBefore,Full(parent,root,solver),label+" parent isolation");
        }
        void CheckNative(string label)
        {
            Equal(State(lanes[0],root),ContinuationStamp.CaptureLive(live).StateText,label+" native complete state/RNG");
            AssertSnapshotEqual(CaptureSimulated(lanes[0],(SimulatedCombatState)lanes[0].State.CombatState,player,root.Enemies[0]),
                CaptureActual(live,player,root.Enemies[0]),"FINITE-SOURCE",label);
            Equal(parentBefore,Full(parent,root,solver),label+" old root after native mutation");
            steps.Add(new{label,projectedFullSha256=Hash(Canonical(lanes[0],root,solver)),nativeSha256=Hash(State(lanes[0],root)),
                shivs=player.PlayerCombatState!.AllCards.Count(card=>card.Id.Entry=="SHIV"),
                inkyCards=player.PlayerCombatState.AllCards.Count(card=>card.Enchantment is Inky),
                hand=player.PlayerCombatState.Hand.Cards.Count});
        }
        foreach(string id in new[]{"NOXIOUS_FUMES","MASTER_PLANNER","FAN_OF_KNIVES","BLADE_OF_INK","BACKSTAB"})
        {
            string liveBefore=ContinuationStamp.CaptureLive(live).StateText;
            foreach(var sim in lanes)Shadow(sim,current=>
            {
                var card=current.State.GetPlayerCombatState(player).Hand.Cards.Single(card=>card.Preview.Id.Entry==id);
                Creature? target=id=="BACKSTAB"?root.Enemies[0]:null;
                if(!current.ManualPlay(card,target,out _))throw new InvalidOperationException("Not playable: "+id);
            });
            CheckShadow(id);Equal(liveBefore,ContinuationStamp.CaptureLive(live).StateText,id+" shadow/live isolation");
            CardModel native=player.PlayerCombatState!.Hand.Cards.Single(card=>card.Id.Entry==id);
            Creature? nativeTarget=id=="BACKSTAB"?root.Enemies[0]:null;
            GameAction action=await SolverController.EnqueueAndCaptureActionAsync(
                action=>action is PlayCardAction played&&ReferenceEquals(played.NetCombatCard.ToCardModelOrNull(),native),
                ()=>{if(!native.TryManualPlay(nativeTarget))throw new InvalidOperationException("Native not playable: "+id);},deadline.Token);
            await action.CompletionTask.WaitAsync(deadline.Token);CheckNative(id);
        }
        CardModel nativeBlade=player.PlayerCombatState!.DiscardPile.Cards.Single(card=>card.Id.Entry=="BLADE_OF_INK"&&card.IsSlyThisTurn);
        foreach(var sim in lanes)Shadow(sim,current=>
        {
            var card=current.State.FindCard(nativeBlade)??throw new InvalidOperationException("Missing tracked Blade.");
            if(!current.AddToPile(card,PileType.Hand).Success)throw new InvalidOperationException("Shadow Blade return rejected.");
        });
        CheckShadow("fixture_move_blade_to_hand");
        if(!(await CardPileCmd.Add(nativeBlade,PileType.Hand)).success)throw new InvalidOperationException("Native Blade return rejected.");
        CheckNative("fixture_move_blade_to_hand");
        foreach(var sim in lanes)Shadow(sim,current=>current.Discard(current.State.FindCard(nativeBlade)??throw new InvalidOperationException("Missing Blade before Sly.")));
        CheckShadow("sly_discard_auto_play");
        await CardCmd.Discard(new BlockingPlayerChoiceContext(),nativeBlade);
        await RunManager.Instance.ActionExecutor.FinishedExecutingActions();CheckNative("sly_discard_auto_play");
        int beforeFrantic=player.PlayerCombatState.AllCards.Count(card=>card.Id.Entry=="FRANTIC_ESCAPE");
        if(player.PlayerCombatState.ExhaustPile.Cards is not List<CardModel> actualExhaust)throw new InvalidOperationException("Unknown native pile storage.");
        var original=actualExhaust.ToArray();
        CardModel[][] orders=[original.OrderBy(card=>card.GetType().FullName,StringComparer.Ordinal).ToArray(),
            original.OrderByDescending(card=>card.GetType().FullName,StringComparer.Ordinal).ToArray(),original];
        string? endedFull=null;SimulationSnapshot? expected=null;CombatRootSnapshot? endRoot=null;
        var ends=new List<object>();
        foreach(var order in orders)
        {
            actualExhaust.Clear();actualExhaust.AddRange(order);
            var captured=CombatRootSnapshot.Capture(live);var driver=new CombatBeamSolver(captured,names,BattleDamageTracker.Observe(live),policy,potionPolicyOverride:SolverPotionPolicy.Disabled);
            SimulationSnapshot end;using(SimulationNotificationIsolation.Enter())end=driver.ReplayEndTurnForTesting();
            if(end.Simulator.HasPendingChoice)throw new InvalidOperationException("Unexpected end-turn choice.");
            string full=Canonical(end.Simulator,captured,driver);
            if(endedFull is null)endedFull=full;else Equal(endedFull,full,"source-populated next turn under exhaust permutation");
            ends.Add(new{hash=Hash(full),frantic=end.Simulator.State.GetPlayerCombatState(player).AllCards.Count(card=>card.Preview.Id.Entry=="FRANTIC_ESCAPE")});
            expected=end;endRoot=captured;
        }
        int previous=player.PlayerCombatState.TurnNumber;CombatManager.Instance.OnEndedTurnLocally();
        var ending=new EndPlayerTurnAction(player,previous);RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue(ending);
        await ending.CompletionTask.WaitAsync(deadline.Token);
        while(player.PlayerCombatState is not{Phase:PlayerTurnPhase.Play} current||current.TurnNumber<=previous)
        {deadline.Token.ThrowIfCancellationRequested();EnsureWithinDeadline();await NextFrameAsync();}
        if(expected is null||endRoot is null)throw new InvalidOperationException("No generated-source end reference.");
        Equal(State(expected.Simulator,endRoot),ContinuationStamp.CaptureLive(live).StateText,"native generation next-turn full state/RNG");
        int afterFrantic=player.PlayerCombatState.AllCards.Count(card=>card.Id.Entry=="FRANTIC_ESCAPE");
        if(afterFrantic!=beforeFrantic+6)throw new InvalidOperationException("Native Liquify did not generate exactly six FranticEscape cards.");
        var sandpit=live.Enemies.SelectMany(enemy=>enemy.Powers).OfType<SandpitPower>().Single(power=>power.Target==player.Creature);
        var output=new{steps,ends,beforeFrantic,afterFrantic,nativeSandpitAmount=sandpit.Amount,
            root.CapturedRunModSubscriberCount,root.CapturedCombatModSubscriberCount,root.CapturedBaseLibCardModifiers,
            nativeEndedSha256=Hash(ContinuationStamp.CaptureLive(live).StateText),actualPrunes=0,wholeRootCertificate=false};
        File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/exhaust-finite-source-pipeline-20261008/native-details.json",JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));
        _completedChecks.Add("FiniteSourcePipeline:ThreeStableWithinTypeExhaustOrders:FiveNativePlays:ShivInkyAndSlyGeneration:NativeSlyAutoPlay:CompleteStateHistoryRng:ParentLiveIsolation:ThreeEndTurns:NativeSixFranticEscapeAndSandpit");
        _completedChecks.Add("TASK_FINITE_SOURCE_PIPELINE "+JsonSerializer.Serialize(output));
    }
}

